<script setup lang="ts">import{computed,ref}from'vue';import{onLoad,onPullDownRefresh}from'@dcloudio/uni-app';import WareState from'@/shared/components/WareState.vue';import WarePhoneLink from'@/shared/components/WarePhoneLink.vue';import{agriDriverApi}from'../../api/agri-driver.api';import{sessionStore}from'@/store/session';const id=ref(''),data=ref<any>(),loading=ref(true),submitting=ref(false),error=ref('');const canOperate=computed(()=>sessionStore.can('agriDriverOrder.operate')&&[1,2].includes(Number(data.value?.order?.orderStatus)));async function load(){loading.value=true;error.value='';try{data.value=await agriDriverApi.detail(id.value)}catch(e){error.value=e instanceof Error?e.message:'订单详情加载失败'}finally{loading.value=false;uni.stopPullDownRefresh()}}async function operate(){if(submitting.value)return;uni.chooseImage({count:1,sourceType:['camera','album'],success:async result=>{submitting.value=true;try{const uploaded=await agriDriverApi.upload(result.tempFilePaths[0]);await agriDriverApi.operate(id.value,data.value.order.orderStatus===1?'ship':'receive',uploaded.url);uni.showToast({title:data.value.order.orderStatus===1?'发货成功':'签收成功',icon:'success'});await load()}catch(e){uni.showToast({title:e instanceof Error?e.message:'操作失败',icon:'none'})}finally{submitting.value=false}}})}onLoad(q=>{id.value=String(q?.id||'');load()});onPullDownRefresh(load);</script>
<template><view class="page"><WareState v-if="loading" type="loading" title="正在加载农资订单详情"/><WareState v-else-if="error" type="error" title="加载失败" :description="error" action-label="重试" @action="load"/><template v-else-if="data"><view class="info"><view class="head"><b>{{data.order.orderId}}</b><span :class="`s${data.order.orderStatus}`">{{data.order.statusLabel}}</span></view><view><text>基地</text><b>{{data.order.baseName}}</b></view><view><text>购买供应商</text><b>{{data.order.buySupplierName}}</b></view><view><text>农资供应商</text><b>{{data.order.peasantSupplierName}}</b></view><view><text>收件人</text><b>{{data.order.receiverName}}</b></view><view><text>收件电话</text><WarePhoneLink :phone="data.order.receiverPhone" compact/></view><view><text>收件地址</text><b>{{data.order.receiverAddress}}</b></view><view><text>下单时间</text><b>{{data.order.createTime}}</b></view><view v-if="data.order.shipTime"><text>发货时间</text><b>{{data.order.shipTime}}</b></view><view v-if="data.order.completeTime"><text>签收时间</text><b>{{data.order.completeTime}}</b></view><view v-if="data.order.completeUserName"><text>签收人</text><b>{{data.order.completeUserName}}</b></view><view v-if="data.order.buyerMemo"><text>备注</text><b>{{data.order.buyerMemo}}</b></view></view><view class="table-head"><text>商品/规格</text><text>数量</text><text>金额</text></view><view v-for="x in data.items" :key="x.id" class="item"><view><b>{{x.goodsName}}</b><small>{{x.skuName}}</small></view><b>{{x.quantity}} 件</b><b>¥{{x.totalPrice.toFixed(2)}}</b></view><button v-if="canOperate" class="primary" :disabled="submitting" @click="operate">{{submitting?'正在提交':data.order.orderStatus===1?'拍照发货':'拍照签收'}}</button></template></view></template>
<style scoped>.page{min-height:100vh;padding:18rpx 20rpx 130rpx;background:var(--wms-background)}.info{padding:17rpx;background:#fff}.head,.info>view{display:flex;align-items:flex-start;justify-content:space-between;gap:15rpx;margin-top:11rpx}.head{margin:0 0 15rpx;padding-bottom:12rpx;border-bottom:1rpx solid var(--wms-border)}.head>b{font-size:24rpx}.head span{padding:3rpx 8rpx;border-radius:5rpx;font-size:17rpx}.s1{background:#f0f2f2}.s2{background:#fff1da;color:#9b5c00}.s3{background:var(--wms-surface-soft);color:var(--wms-success)}.info>view>text{width:110rpx;flex:none;color:var(--wms-text-secondary);font-size:19rpx}.info>view>b{font-size:20rpx;text-align:right}.table-head,.item{display:grid;grid-template-columns:minmax(0,1.6fr) 80rpx 100rpx;gap:8rpx;align-items:center}.table-head{margin-top:14rpx;padding:12rpx;background:var(--wms-primary-700);color:#fff;font-size:18rpx}.item{margin-top:5rpx;padding:13rpx;background:#fff;font-size:19rpx}.item small{display:block;margin-top:5rpx;color:var(--wms-text-secondary);font-size:17rpx}.primary{position:fixed;z-index:10;right:20rpx;bottom:24rpx;left:20rpx;height:76rpx;background:var(--wms-primary-700);color:#fff;font-size:22rpx;line-height:76rpx}.primary:after{border:0}</style>
